    /// &strをbyte列として追加
    /// ASCII文字を想定
    #[inline(always)]
    pub fn insert(&mut self, word: &str) {
        self.insert_bytes(word.as_bytes());
    } // end of method

    /// &[u8]をそのまま追加
    /// 任意の1byte文字
    #[inline(always)]
    pub fn insert_bytes(&mut self, word: &[u8]) {
        // rootから開始, 全体の文字列数とrootを通る文字列数をカウント
        let mut current_index: usize = 0;
        self.len += 1;
        self.nodes[current_index].pass_count += 1;

        for &byte in word.iter() {
            // すでに辺があるなら子ノードへ進む
            let next_index = if let Some(&child_index) = self.nodes[current_index].children.get(&byte) {
                child_index
            }
            // 辺がないなら新しくノードを作る
            else {
                let child_index = self.nodes.len();
                self.nodes.push(ByteTrieNode::new());
                self.nodes[current_index].children.insert(byte, child_index);
                child_index
            };

            // このノードを通る文字列数をカウント
            current_index = next_index;
            self.nodes[current_index].pass_count += 1;
        }

        self.nodes[current_index].end_count += 1;
    } // end of method

    /// &strと完全一致する文字列が存在するか
    #[inline(always)]
    pub fn contains(&self, word: &str) -> bool {
        return self.count_word(word) > 0;
    } // end of method

