    /// &[u8]を1個削除
    #[inline(always)]
    pub fn remove_bytes(&mut self, word: &[u8]) -> bool {
        let mut current_index: usize = 0;

        // 削除後に不要な辺を消すために通った経路を保存
        // current_indexからbyteでchild_indexへ移動
        let mut path: Vec<(usize, u8, usize)> = Vec::with_capacity(word.len());

        // byteを1つずつたどる
        for &byte in word.iter() {
            // 次の辺が存在しないならこの単語は登録されていない
            let Some(&child_index) = self.nodes[current_index].children.get(&byte) else {
                return false;
            };

            path.push((current_index, byte, child_index));
            current_index = child_index;
        }

        // 終端ノードに到達しても, そこで終わる単語がないなら完全一致ではない
        // abcが登録されていて, abを削除しようとした
        if self.nodes[current_index].end_count == 0 {
            return false;
        }

        // 全体の単語, rootのカウントを減らす
        self.len -= 1;
        debug_assert!(self.nodes[0].pass_count > 0);
        self.nodes[0].pass_count -= 1;

        // 通ったノードのカウントを減らす
        for &(_, _, child_index) in path.iter() {
            debug_assert!(self.nodes[child_index].pass_count > 0);
            self.nodes[child_index].pass_count -= 1;
        }

        // 終端ノードで終わる単語数を1つ減らす
        debug_assert!(self.nodes[current_index].end_count > 0);
        self.nodes[current_index].end_count -= 1;

        // 後ろから見て, もう使用されていないノードへの辺を削除
        for &(parent_index, byte, child_index) in path.iter().rev() {
            if self.nodes[child_index].pass_count == 0 {
                self.nodes[parent_index].children.remove(&byte);
            } else {
                break;
            }
        }
        return true;
    } // end of method

    /// 登録されている文字列数
