    /// wordの終端ノード番号を返す
    #[inline(always)]
    fn get_node_index(&self, word: &[u8]) -> Option<usize> {
        let mut current_index = 0;

        // byteを1つずつたどる
        for &byte in word.iter() {
            match self.nodes[current_index].children.get(&byte) {
                Some(&child_index) => {
                    current_index = child_index;
                }
                None => {
                    return None;
                }
            }
        }

        return Some(current_index);
    } // end of method

    /// 他の単語との最長共通プレフィックスを求める
    #[inline(always)]
    pub fn max_lcp_with_other(&self, word: &[u8]) -> usize {
        let mut current_index: usize = 0;
        let mut depth: usize = 0;

        // 最大LCP長
        let mut answer: usize = 0;

        for &byte in word.iter() {
            // このbyteの辺がなければ終了
            let Some(&next_index) = self.nodes[current_index].children.get(&byte) else {
                break;
            };

            // 1文字先に
            depth += 1;
            current_index = next_index;

            // pass_countが2以上なら, 自分以外にもこのprefixを持つ文字列があるはず
            if self.nodes[current_index].pass_count >= 2 {
                answer = depth;
            }
        }

        return answer;
    } // end of method
